package com.example.yuejie;
import android.graphics.*;import android.graphics.drawable.Drawable;
final class SettingsToolIcon extends Drawable {final String label;final int size;final boolean selected;final Paint p=new Paint(3);final Path path=new Path();SettingsToolIcon(String label,int color,int size){this(label,color,size,false);}SettingsToolIcon(String label,int color,int size,boolean selected){this.selected=selected;this.label=label;this.size=size;p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.6f);p.setStrokeJoin(Paint.Join.ROUND);p.setStrokeCap(Paint.Cap.ROUND);}public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}public void draw(Canvas c){c.save();c.translate(getBounds().left,getBounds().top);c.scale(getBounds().width()/24f,getBounds().height()/24f);path.reset();if(label.equals("目录")){c.drawRoundRect(5,3,19,21,2,2,p);c.drawLine(9,9,15,9,p);c.drawLine(9,13,15,13,p);}else if(label.equals("书签")){path.moveTo(6,3);path.lineTo(18,3);path.lineTo(18,21);path.lineTo(12,17);path.lineTo(6,21);path.close();c.drawPath(path,p);}else if(label.equals("设置")){for(int i=0;i<6;i++){double a=Math.PI*i/3;float x=12+10*(float)Math.cos(a),y=12+10*(float)Math.sin(a);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();if(selected){p.setStyle(Paint.Style.FILL);c.drawPath(path,p);p.setStyle(Paint.Style.STROKE);int color=p.getColor();p.setColor(Color.WHITE);c.drawCircle(12,12,2.5f,p);p.setColor(color);}else{c.drawPath(path,p);c.drawCircle(12,12,2.5f,p);}}else if(label.equals("夜间")){path.moveTo(13,2);path.cubicTo(17,2.5f,19.5f,6,20,7);path.moveTo(13,2);path.cubicTo(17,11,10,16,3,14);path.cubicTo(4,20,9,23,15,21);path.cubicTo(20,19,22,15,21,10);c.drawPath(path,p);}else{c.drawCircle(12,12,5,p);for(int i=0;i<8;i++){double a=Math.PI*i/4;c.drawLine(12+8*(float)Math.cos(a),12+8*(float)Math.sin(a),12+10*(float)Math.cos(a),12+10*(float)Math.sin(a),p);}}c.restore();}public void setAlpha(int a){p.setAlpha(a);}public void setColorFilter(ColorFilter f){p.setColorFilter(f);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}}
